@startuml

class Bus {
  + line_number : string
}

class Trajectory {
  + Status : string
}

class Line {
  + Destination : string
}

class PriceCategory {
  + Price : double
}

class MensoTicket {
  + ValidityPeriod : string
}

class Trip {
  + Time : time
  + Date : date
}

class Invoice {
  + TotalAmount : double
  + Discount : double
}

class Customer {
  + HomeAddress : string
  + OfficeAddress : string
  + WorkingHours : string
}

class TicketMachine {}

class MensoCard {}

class RegularTicket {}

Bus "1" -- "*" Trajectory
Line "1" -- "*" Trajectory
Line "1" -- "1" PriceCategory
Bus "1" -- "*" Line
MensoTicket "1" -- "1" Customer
MensoTicket "1" -- "0..*" Trip
Line "1" -- "0..*" Trip
Trip "1" -- "1" Invoice
Customer "1" -- "0..*" Invoice
TicketMachine "1" -- "0..*" Trip
MensoCard "1" -- "0..*" Trip
RegularTicket "1" -- "0..*" Trip

@enduml

